window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"VvNTEOD6ziI","speaker":"Luca Beccari","role":"Foreign Minister","country":"San Marino","region":"Europe","url":"https://www.youtube.com/watch?v=VvNTEOD6ziI","date":"20260926","title":"🇸🇲 San Marino - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1181,"words":2449,"counts":{"claims":32,"promises":3,"attacks":0},"topics":[{"topic":"Israel-Palestine","share":0.1678,"seconds":198},{"topic":"International law","share":0.1134,"seconds":134},{"topic":"Iran","share":0.0646,"seconds":76},{"topic":"San Marino-EU relations","share":0.0614,"seconds":73},{"topic":"UN Charter","share":0.0606,"seconds":72},{"topic":"Children in conflict","share":0.0566,"seconds":67},{"topic":"Afghanistan","share":0.0556,"seconds":66},{"topic":"Nuclear weapons","share":0.0538,"seconds":64},{"topic":"Sustainable development","share":0.0535,"seconds":63},{"topic":"AI governance","share":0.0531,"seconds":63},{"topic":"UN General Assembly","share":0.0526,"seconds":62},{"topic":"International criminal justice","share":0.0523,"seconds":62},{"topic":"UN Security Council reform","share":0.052,"seconds":61},{"topic":"Ukraine","share":0.0518,"seconds":61},{"topic":"Explosive weapons","share":0.0508,"seconds":60}],"timeline":[[1,62,null],[63,135,"San Marino-EU relations"],[137,200,"International law"],[202,264,"UN General Assembly"],[266,336,"International law"],[336,398,"UN Security Council reform"],[398,464,"Israel-Palestine"],[465,534,"Israel-Palestine"],[535,598,"Israel-Palestine"],[599,675,"Iran"],[676,737,"Ukraine"],[739,799,"Explosive weapons"],[800,862,"International criminal justice"],[863,928,"Afghanistan"],[931,998,"Children in conflict"],[998,1062,"Nuclear weapons"],[1063,1126,"Sustainable development"],[1127,1190,"AI governance"],[1191,1262,"UN Charter"]],"stances":{"San Marino-EU relations":"Luca Beccari states that the upcoming association agreement with the European Union is a fundamental milestone for San Marino that deepens cooperation while preserving sovereignty.","International law":"Luca Beccari states that the principles of cooperation and dialogue are essential for small states to exercise sovereignty, but notes that these principles and international law are currently under pressure due to multiplying conflicts and violations.","UN General Assembly":"Luca Beccari expresses support for the elected president and the Secretary-General while emphasizing the need for effective multilateralism.","UN Security Council reform":"Luca Beccari advocates for a more representative, transparent, and accountable UN Security Council with greater regional representation and equitable geographical distribution, while supporting efforts to restrain the use of the veto.","Israel-Palestine":"Luca Beccari condemns terrorism while affirming the Palestinian right to self-determination and rejecting collective punishment.","Iran":"Luca Beccari expresses deep concern regarding hostility involving Iran and threats to maritime security in the Red Sea and Strait of Hormuz, while calling for respect of freedom of navigation.","Ukraine":"Luca Beccari asserts that no state may redraw borders by force and calls for an immediate ceasefire to ensure Ukrainian sovereignty, independence, and territorial integrity.","Explosive weapons":"Luca Beccari condemns the use of explosive weapons in populated areas and calls for the implementation of related political declarations.","International criminal justice":"Luca Beccari asserts that accountability is essential for lasting peace and calls on state parties to defend the International Criminal Court's independence against recent political pressure.","Afghanistan":"Luca Beccari asserts that the systematic denial of rights to Afghan women and girls is unacceptable and calls for their full restoration.","Children in conflict":"Luca Beccari states that children deserve protection from harm in armed conflicts and calls for the ratification of relevant protocols.","Nuclear weapons":"Luca Beccari states that San Marino remains committed to a nuclear-weapon-free world and supports the treaties on non-proliferation and prohibition of nuclear weapons.","Sustainable development":"Luca Beccari states that commitments to the SDGs are insufficient and emphasizes the need for concrete implementation, financing, accountability, and a fair international financial architecture.","AI governance":"Luca Beccari argues that while artificial intelligence offers opportunities, it creates risks that require international governance to ensure technology serves humanity and does not undermine human rights or peace.","UN Charter":"Luca Beccari states that San Marino will continue to defend the UN Charter, international law, and multilateralism while emphasizing the need for cooperation over division."},"claims":[{"t":99,"quote":"The forthcoming signing of the association agreement with the European Union on 19th October will mark a milestone for our country.","topic":"San Marino-EU relations","kind":"fact"},{"t":160,"quote":"81 years ago, the United Nation was created to save succeeding generation from the scourge of war.","topic":"International law","kind":"fact"},{"t":193,"quote":"We are witnessing violation of international law, humanitarian and humanit and human right law.","topic":"International law","kind":"fact"},{"t":229,"quote":"congratulate his helen Dr. Khalu Raman on his election as a president of the 81st section of the general assembly","topic":"UN General Assembly","kind":"fact"},{"t":273,"quote":"Sovereignity, territorial integrity, political independence and self-determination matter. This principle are not optional and they cannot depend on the size of a country or the power of a government.","topic":"International law","kind":"fact"},{"t":295,"quote":"For San Marino, this is not an abstract principle. For small state, international law is our protection. It is the ultimate equalizer.","topic":"International law","kind":"fact"},{"t":341,"quote":"San Marino is also a member of the uniting for consensus group and support its effort to promote a comprehensive and balanced reform of the security council based on a greater regional representation equitable geographical distribution and wider access to elected seat.","topic":"UN Security Council reform","kind":"fact"},{"t":370,"quote":"We support effort to restrain the use of the veto including the French Mexican initiative and the ACT code of conduct in a situation involving mass atrocity alongside the general assembly veto initiative.","topic":"UN Security Council reform","kind":"fact"},{"t":429,"quote":"the horrific attack of 7 October 2023","topic":"Israel-Palestine","kind":"fact"},{"t":436,"quote":"The Palestinian people have an annihilable right to self-determination and to their own state","topic":"Israel-Palestine","kind":"fact"},{"t":513,"quote":"The situation is rapidly deteriorating. I mean unprecedented level of settle violence and settlement expansion included in an un an acceptable decision to punish tender for the E1 settlement This development undermined the possibility of a viable Palestinian state.","topic":"Israel-Palestine","kind":"fact"},{"t":545,"quote":"Last year, San Marino endorses the New York declaration for a two-state","topic":"Israel-Palestine","kind":"fact"},{"t":552,"quote":"Following an anonymous mandate from our parliament, a great and general council, San Marino recognized Palestine as a sovereign and independent state within secure and international recognized border and in accordance with relevant United Nation resolution.","topic":"Israel-Palestine","kind":"fact"},{"t":599,"quote":"We are deeply concerned by no hostility involving Iran and by threat to maritime security in the Red Sea and the Strait of Ormouth.","topic":"Iran","kind":"fact"},{"t":658,"quote":"Samarino condemned Russian and ongoing aggression against Ukraine, the bombardment of city, the killing of civilian, attack on humanitarian workers, the unlawful deportation of","topic":"Iran","kind":"fact"},{"t":676,"quote":"They are violation of international law. No state can be allowed to redraw border by force.","topic":"Ukraine","kind":"fact"},{"t":722,"quote":"International humanitarian law was created precisely for these circumstances. It does not disappear in time of war.","topic":"Ukraine","kind":"fact"},{"t":739,"quote":"San Marino strongly condemn the use of explosive weapon in populated area","topic":"Explosive weapons","kind":"fact"},{"t":758,"quote":"Hate worker and journalist are not legitimate target","topic":"Explosive weapons","kind":"fact"},{"t":800,"quote":"The court exists because the gravest crime cannot go unhanced for it. Genocide, war crimeing, crime against humanity.","topic":"International criminal justice","kind":"fact"},{"t":841,"quote":"San Marino also reaffirm its historic commitment to the abolition of the death penalty which it abolished in This reflect our enduring conviction that human human dignity must be protect even in the face of the gravest crime.","topic":"International criminal justice","kind":"self_credit"},{"t":868,"quote":"five year ago the Taliban sized power in Afghanistan. Five years is too long for half of our population to be denied its right.","topic":"Afghanistan","kind":"fact"},{"t":889,"quote":"Girl remain excluded from secondary and higher education. Women are increasing excluded from public life.","topic":"Afghanistan","kind":"fact"},{"t":934,"quote":"Children are being killed, maimed, abducted and recruited. There are losing their home, their school and their future.","topic":"Children in conflict","kind":"fact"},{"t":957,"quote":"We have endorsed the safe school declaration, the Paris principle and the Vancouver principle.","topic":"Children in conflict","kind":"self_credit"},{"t":1012,"quote":"We also proudly uphold the treaty on the prohibition of nuclear weapon which Samarino has signed and ratified.","topic":"Nuclear weapons","kind":"fact"},{"t":1038,"quote":"clim climate change increased pressure on food, water and community.","topic":"Nuclear weapons","kind":"fact"},{"t":1090,"quote":"The triple planetary crisis, climate change, biodiversity, loss and pollution is already affecting peace and security, environmental degradation, full food insecurity, water scarcity and displacement.","topic":"Sustainable development","kind":"fact"},{"t":1122,"quote":"Conflict and climate shock are driving anger and malnutrition.","topic":"Sustainable development","kind":"fact"},{"t":1127,"quote":"San Marino believe that reducing food loss and waste is one practical contribution of a more secure and sustainable food system.","topic":"AI governance","kind":"fact"},{"t":1140,"quote":"Artificial intelligence and emerging technology offer enormous opportunity but they also create new risk.","topic":"AI governance","kind":"fact"},{"t":1204,"quote":"for more than 17 centuries, San Marino has showed that a small state can state can preserve its independence through dialogue, respect for the law, and engagement with the international community.","topic":"UN Charter","kind":"fact"}],"promises":[{"t":238,"quote":"Samarino support the priority of your program and stand ready to cooperate fully with you and with all member state in the year ahead","topic":"UN General Assembly","kind":"promise"},{"t":1217,"quote":"This is why San Marino will continue to defend the United Nation Charter, international law, human right and multilateralism.","topic":"UN Charter","kind":"promise"},{"t":1235,"quote":"San Marino will do its part.","topic":"UN Charter","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"I now give the floor to his excellency Lucura Bakari, Minister of Foreign Affairs, Political Affairs, International Economical Cooperation and Digital Transition of San Mario, Mr. President, Mr. Your secretary general, excellencies, ladies and gentlemen, San Marino is the world oldest republic. For more than 17 centuries, we have survived not through military power, territorial expansion, economic might, but through dialogue, respect for the law, neutrality, and then conviction that sovereignty of a small state is no less valuable than that of a great power. Our history has taught a simple lesson."},{"t":63,"topic":"San Marino-EU relations","text":"When power is not enough to protect you, rule matter. When you cannot impose your will, dialogue matter. And when the world is divide, institution that brings stay together matter. This is why multilateralism is not an abstract concept for San Marino. is a fundamental principle of our foreign policy and in many ways election drew from our own history. Our commitment to cooperation and share rule is also reflected in our relationship with the European Union. The forthcoming signing of the association agreement with the European Union on 19th October will mark a milestone for our country. It represent an historical step toward closer cooperation. shared rule and greater integration within the European Union while fully preserving our sovereignity, the entity and institutional For some Marino, this is not simply an agreement about economic relation is a long-term choice to deepen our engagement with Europe while preserving the distinctive character of our republic."},{"t":137,"topic":"International law","text":"It is a choice that reflect a principle at the heart of our history. Cooperation does not diminish sovereignity. For a small state, cooperation, rule, and dialogue are precisely what allow sovereignity to be exercised and protect. Today, that principle is under extraordinary pressure. 81 years ago, the United Nation was created to save succeeding generation from the scourge of war. Yet today conflict are multiplying, inequality are deepening, climate disruption is accelerating, food and water are being used an instrument of pressure and the rule that have governed international relation for decades are being challenged. We are witnessing the use of force against sovereign state. We are witnessing violation of international law, humanitarian and humanit and human right law."},{"t":202,"topic":"UN General Assembly","text":"At such a moment the answer cannot be less multilateralism. It must be more and it must be a multilateral that works that protect the weak as well the strong on that apply the low equality and one that give every state large or small a meaningful voice before turning to the challenge before us allow me to congratulate his helen Dr. Khalu Raman on his election as a president of the 81st section of the general assembly. Samarino support the priority of your program and stand ready to cooperate fully with you and with all member state in the year ahead. I also wish to express our appreciation to Secretary General Antonio Gutirez for his leadership at a time of profound international uncertainity and for his continuing effort to strain the United Nation multilateral system."},{"t":266,"topic":"International law","text":"Mr. President, there can no there can be no word in which might make right. Sovereignity, territorial integrity, political independence and self-determination matter. This principle are not optional and they cannot depend on the size of a country or the power of a government. There can be no impunity for violation of international law. The law must apply to all. For San Marino, this is not an abstract principle. For small state, international law is our protection. It is the ultimate equalizer. A rule-based international order allow every state large or small to have an equal voice and equal legal standing. This is why San Marino strongly support the secretary general general UN8 initiative. The United Nation must be must become more effective, more efficient and more responsive and reform must include the security The council must better reflect today word."},{"t":336,"topic":"UN Security Council reform","text":"It must be more representative, transparent and accountable. San Marino is also a member of the uniting for consensus group and support its effort to promote a comprehensive and balanced reform of the security council based on a greater regional representation equitable geographical distribution and wider access to elected seat. Reform must train the voice of all member state including a small state and it must be achieved through broad consensus. We support effort to restrain the use of the veto including the French Mexican initiative and the ACT code of conduct in a situation involving mass atrocity alongside the general assembly veto initiative. We also reaffirm our full support for the international court of Its order and jud judgment are legally Mr."},{"t":398,"topic":"Israel-Palestine","text":"President, the next secretary general will carry a vital responsibility. The United Nation must remain relevant and credible. Above all, it must remain capable of protecting people and upholding the charter. Samarino stand ready to contribute. I now turn to one of the most painful crisis of our time. The situation in the Middle East demand clarity. San Marino inequivocally condemned terrorism including the horrific attack of 7 October 2023. But we must be equally clear on another point. The Palestinian people have an annihilable right to self-determination and to their own state. State is not a reward for terrorism. It's a right. At the same time, nothing can justify the collective punishment of civilian. The in the suffering in Gaza cannot became new normal. We call for a permanent chase farfar and for full safe and humanitarian access."},{"t":465,"topic":"Israel-Palestine","text":"Humanitarian assistance must reach those who need it. Civilian live must be protect. UN RWBA and other humanitarian organization must be able to operate. We call for the permanent disarmament of Hamas and order non-state armored group and for the withdrawal of Israeli force from the Gaza Strip. We support the Palestinian Authority and his reform efforts including democratic election. We urge Israel to release withheld clearance revenue and to facilitate correspondent banking service for the Palestinian Authority in the West Bank and the East Jerusalem. Settlement, expansion, settle violence, land appropriation, demolition and election and eviction must stop. The situation is rapidly deteriorating. I mean unprecedented level of settle violence and settlement expansion included in an un an acceptable decision to punish tender for the E1 settlement This development undermined the possibility of a viable Palestinian state."},{"t":535,"topic":"Israel-Palestine","text":"The status quo of Jerusan holy site must be respect. All community including Christian community must be Last year, San Marino endorses the New York declaration for a two-state Following an anonymous mandate from our parliament, a great and general council, San Marino recognized Palestine as a sovereign and independent state within secure and international recognized border and in accordance with relevant United Nation resolution. We stand by that decision. There is no alternative to the two state living side by side in peace, security and mutual recognition. The window for that solution is narrowing. We must act now. Mr. President, the consequences of the conflict extended far beyond Gaza and the West Bank. Escalation across the region, threatening international peace and security."},{"t":599,"topic":"Iran","text":"We are deeply concerned by no hostility involving Iran and by threat to maritime security in the Red Sea and the Strait of Ormouth. Freedom of navigation is essential to global International law including EU hand clause must be respect in Lebanon. We call for full respect for sovereignity and for the implementation implementation of security council Civilian infrastructure must be protected in Syria. We support an inclusive and peaceful political transition that respect sovereignity, protect civilian and strain institution. Peace cannot be imposed by force. It require diplomacy and dialogue and it require international role. Mr. President, Europe Europe is also facing a war that continue to cause immense humanitarian suffering. Samarino condemned Russian and ongoing aggression against Ukraine, the bombardment of city, the killing of civilian, attack on humanitarian workers, the unlawful deportation of These are not simply in tragedy."},{"t":676,"topic":"Ukraine","text":"They are violation of international law. No state can be allowed to redraw border by force. San Marino therefore reiterate his call for a full immediate and unconditional chasefire leading to a comprehensive just and lasting peace. Any peace must respect Ukrainian sovereignity, independence and territorial integrity within its internationally recognized border. Mr. President from Ukraine to Gaza, from Sudan to Syria, from the Shahel to Afghanistan, civilian continue to pay the heights price. Woman, children, older people, family forces from their home, hospital and school destroy, food, water, and medicine denied. International humanitarian law was created precisely for these circumstances. It does not disappear in time of war. It is not suspended by political convenience. It must be respect."},{"t":739,"topic":"Explosive weapons","text":"San Marino strongly condemn the use of explosive weapon in populated area and call for all state to implementation implement the political declaration on explosive weapon in populated area. Those who deliver humanitarian assistance must also be protect. Hate worker and journalist are not legitimate target. San Marino also reaffirm its commitment to the Australia lead declaration for the protection of humanitarian personnel and call on all parties to armed conflict to respect and protect humanitarian personnel and to ensure that assistance can reach those in need. Impunity cannot became normal. San Marino therefore reaffirm his commitment to the Geneva Convention, the Zenocide Convention and the Roman And we reiterate our unwing support for the International Criminal Court."},{"t":800,"topic":"International criminal justice","text":"The court exists because the gravest crime cannot go unhanced for it. Genocide, war crimeing, crime against humanity. Accountability is not an obstacle to peace. It is a part of a lasting peace. The fight against impunity is also an essential element of the responsibility to protect with must remain a shared responsibility of the international Recent political pressure and coercive measure against the court is official and those who cooperate within it are deeply concerning. State parties to the Rome statue must defend the independence and integrity of the Kurd. San Marino also reaffirm its historic commitment to the abolition of the death penalty which it abolished in This reflect our enduring conviction that human human dignity must be protect even in the face of the gravest crime."},{"t":863,"topic":"Afghanistan","text":"Justice cannot depend on political Mr. President five year ago the Taliban sized power in Afghanistan. Five years is too long for half of our population to be denied its right. Afghan women and girl continue to face a systematic restriction on education, employment, movement, public participation and access to justice. Girl remain excluded from secondary and higher education. Women are increasing excluded from public life. This cannot become became normal. San Marino call for the full restoration of the right of Avagan woman and girl. Education is a right. Work is a right. Participation in public life is a right. Dignity is a right. This right do not disappear because a government choose to deny them. The international community must continue to stand with Afghan women and girls. Humanitarian access must also remain under Afghan Afghanistan must not be forgotten."},{"t":931,"topic":"Children in conflict","text":"Mr. President, children everywhere deserve protection. Children are being killed, maimed, abducted and recruited. There are losing their home, their school and their future. San Marino remain firmly committed to the children and harm conflict agenda and support the work of the UN special representative for children and harm conflict. School must remain safe place. We have endorsed the safe school declaration, the Paris principle and the Vancouver principle. We call on all state to strain the protection of children in armed conflict and ratify the optional protocol of the convention of the right of the child. Mr. President, the return of nuclear threat is another source of grave concern. There can be no acceptable nuclear threat or acceptable use of nuclear weapon. The modernization and expansion of nuclear arsenal together with growing military expenditure and the rapid development of artificial and cyber cap capabilities increase the risk of escalation."},{"t":998,"topic":"Nuclear weapons","text":"The consequences of nuclear use will be catastrophic. San Marino remain committed to a war free of nuclear weapon. We support the treaty on the non-prololiferation of nuclear weapon. We also proudly uphold the treaty on the prohibition of nuclear weapon which Samarino has signed and ratified. Diplomacy must prevail over deterrence through fear. Peace and security cannot be separated from development. Nor can develop development be separated from human right. Conflict destroy development gain. Poverty fool instability. clim climate change increased pressure on food, water and community. We must also not overlock the devastating humanitarian and social and economic situation in Cuba where prolonged hardship is placing on immense burden on the daily life of the Cuban people. We must therefore threat peace, security, human right and sustainable development as part of the same agenda."},{"t":1063,"topic":"Sustainable development","text":"The SDG remain our common commitment. The pact for the future provide an opportunity to strain multilateralism and accelerate implementation of the 2030 agenda. But commitments are not enough. We need implementation, financing, and accountability. We also need a fair and more inclusive international financial architecture supported by a degrade resources and greater financial stability for the lean itself. The triple planetary crisis, climate change, biodiversity, loss and pollution is already affecting peace and security, environmental degradation, full food insecurity, water scarcity and displacement. The Paris agreement must be fully implemented. The 1.5 degree goal must remain within reach. The transition must be just and no country should be left behind. Food security must also remain at the heart of our collective effort. Conflict and climate shock are driving anger and malnutrition."},{"t":1127,"topic":"AI governance","text":"San Marino believe that reducing food loss and waste is one practical contribution of a more secure and sustainable food system. We also in entering in a new technological era. Artificial intelligence and emerging technology offer enormous opportunity but they also create new risk. Technology must serve humanity. It must not be used to undermine human right. International peace or international humanitarian law. The rule must keep peace with innovation. And where new technology create new risk, our responsibility is not to look away but to govern them. This is why multilateralism matter. Multilateralism is not an outdated idea. It is not only framework capable of managing an independent world. No country can address today challenge alone, protect itself from climate change alone, prevent the proliferation of nuclear weapon alone or regulate global technology alone."},{"t":1191,"topic":"UN Charter","text":"And no country can build lasting peace alone. We need cooperation and institution that work. And we need the political courage to uphold the rule we have created Mr. President, for more than 17 centuries, San Marino has showed that a small state can state can preserve its independence through dialogue, respect for the law, and engagement with the international community. This is why San Marino will continue to defend the United Nation Charter, international law, human right and multilateralism. At a time when the world is tempted by division, we must choose cooperation. When force challenge law, we must stand firmly by the law. And when the spirits grow, we must choose peace. San Marino will do its part. Together, we must ensure that the United Nation remain what it was created to be, a shield for the vulnerable, a forum of dialogue, and a guardian of peace, dignity, international law. Thank you. &gt;&gt; I thank the Minister of Foreign Affairs, Political Affairs, International Economic Cooperation, and Digital Transition of San Marino."}],"compare":[{"topic":"Israel–Palestine","share":0.1678,"mean":0.0518,"rank":15,"others":76},{"topic":"International Law & Order","share":0.1657,"mean":0.0598,"rank":23,"others":102},{"topic":"UN & its reform","share":0.1652,"mean":0.205,"rank":110,"others":170},{"topic":"Nuclear Weapons","share":0.1046,"mean":0.0019,"rank":1,"others":6},{"topic":"Iran","share":0.0646,"mean":0.0135,"rank":20,"others":25},{"topic":"San Marino","share":0.0614,"mean":0.0,"rank":1,"others":0},{"topic":"Human Rights","share":0.0566,"mean":0.0083,"rank":11,"others":24},{"topic":"Afghanistan","share":0.0556,"mean":0.0015,"rank":4,"others":3}]};
